# Look at column 0 values
print("Column 0 values by row:")
for i, val in enumerate([grid[i][0] for i in range(30)]):
    print(f"  {i}: {val}", end="")
    if (i+1) % 5 == 0:
        print()

# Check for the pattern in terms of vertical symmetry
print("\n\nChecking row relationships:")
# Check if grid[i] relates to grid[29-i] for certain i
for i in range(15):
    match = grid[i] == grid[29-i]
    if match:
        print(f"Row {i} == Row {29-i} (yes)")
    else:
        print(f"Row {i} == Row {29-i} (no)")

# Let me identify the "8-block" pattern
print("\n\nIdentifying the 8-block structure:")
for i in range(30):
    starts_with_8s = grid[i][:3] == [8, 8, 8]
    if starts_with_8s:
        print(f"Row {i}: starts with 8s")
    else:
        count_8s = sum(1 for j in range(5) if grid[i][j] == 8)
        if count_8s > 0:
            print(f"Row {i}: has {count_8s} 8s in first 5 cols")

# Analyze which rows might be "reference" vs "target"
print("\n\nUnique row patterns (starting chars):")
row_starts = [(i, grid[i][:3]) for i in range(30)]
from collections import Counter
start_counts = Counter([r[1] for r in row_starts])
for start, count in start_counts.most_common():
    rows_same = [r[0] for r in row_starts if r[1] == start]
    print(f"{start}: rows {rows_same} ({count} times)")

